import std.io

pub type AppError = Nope | Broken

fn pick(n: Int64) -> Option<Int64> {
    if n > 0 {
        return Some(n)
    }
    return None
}

pub fn main() effect io -> Result<(), AppError> {
    let a = pick(3i64)
    match a {
        Some(v) => { io.println("some ${v}") }
        None => { io.println("none") }
    }
    let b: Option<Int64> = Some(42i64)
    match b {
        Some(v) => { io.println("lit ${v}") }
        None => { io.println("lit none") }
    }
    return Ok(())
}
